var i=`1428-ukaeb`;var a=`world-1428`;var t=`PW`;var o=`oceania`;var s=4;var l=55;var c={en:`Ukaeb`,ua:`Укаеб`};var r={en:`Palauan ukaeb is associated with crab and rich coconut dressing. This home version bakes seasoned crab in ramekins instead of re-stuffing cleaned crab shells.`,ua:`Палауське укаеб, крабова страва з насиченою кокосовою заправкою. Домашня версія запікає крабове м’ясо у формочках замість начинювання очищених панцирів.`};var u=[{en:`Steam cleaned blue crabs until the meat is fully opaque and cooked. Cool enough to handle, then remove all shell and cartilage, keeping about 350 g of crab meat.`,ua:`Приготуйте очищених блакитних крабів на парі до повної готовності м’яса. Трохи остудіть і ретельно видаліть панцир та хрящі, отримавши близько 350 г м’яса.`,t:[`steaming`],m:18,i:[[`blue-crab`,750,`g`]]},{en:`Sauté finely diced onion, garlic and chili in oil until softened.`,ua:`Обсмажте дрібно нарізану цибулю, часник і чилі на олії до м’якості.`,t:[`sauteing`],m:7,i:[[`yellow-onion`,130,`g`],[`garlic`,3,`clove`],[`bird-s-eye-chili`,1,`pcs`],[`vegetable-oil-neutral`,15,`ml`]]},{en:`Stir cornstarch into the cold coconut cream, then fold in cooked crab and the sautéed aromatics; season with salt.`,ua:`Розмішайте крохмаль у холодних кокосових вершках, додайте готове крабове м’ясо й обсмажені овочі; посоліть.`,t:[`mixing`],m:7,i:[[`cornstarch`,12,`g`],[`coconut-cream`,320,`ml`],[`sea-salt`,3,`g`]]},{en:`Divide into four oven-safe ramekins and bake at 190°C for 20 minutes until bubbling and thickened.`,ua:`Розкладіть у чотири жаростійкі формочки й запікайте при 190°C 20 хвилин до загущення та активного булькання.`,t:[`baking`],m:20,i:[]},{en:`Finish with lime juice and chopped spring onions; serve hot.`,ua:`Збризніть соком лайма й посипте подрібненою зеленою цибулею; подавайте гарячим.`,t:[`garnishing`],m:3,i:[[`lime-juice`,20,`ml`],[`spring-onion`,35,`g`]]}];var d={slug:i,id:a,country:`PW`,region:o,servings:4,minutes:55,title:c,text:r,steps:u};export{t as country,d as default,a as id,l as minutes,o as region,s as servings,i as slug,u as steps,r as text,c as title};